import { z } from 'zod';

// Entity extraction schemas - updated for OpenAI structured outputs
// For OpenAI structured outputs with strict mode, ALL fields must be required
// Note: z.record() is not supported by OpenAI structured outputs, so we use an array of key-value pairs
export const ExtractedEntitySchema = z.object({
  name: z.string().describe("The exact name of the entity as mentioned in the text"),
  entity_type: z.string().describe("The type of entity from the provided list"),
  summary: z.string().describe("Brief description of the entity, or empty string if none"),
  attributes: z.array(z.object({
    key: z.string().describe("Attribute name"),
    value: z.string().describe("Attribute value")
  }).strict()).describe("Additional attributes as array of key-value pairs, or empty array"),
}).strict();

export const EntityExtractionResponseSchema = z.object({
  entities: z.array(ExtractedEntitySchema),
}).strict();

export type ExtractedEntity = z.infer<typeof ExtractedEntitySchema>;
export type EntityExtractionResponse = z.infer<typeof EntityExtractionResponseSchema>;

// Entity type definitions based on common writing contexts
export const DEFAULT_ENTITY_TYPES = {
  Person: "People, characters, individuals mentioned by name or role",
  Location: "Places, locations, geographic areas, buildings, rooms",
  Organization: "Companies, groups, institutions, teams, clubs",
  Object: "Physical objects, items, tools, vehicles, books, documents",
  Concept: "Ideas, themes, topics, abstract concepts, skills, emotions",
  Event: "Meetings, ceremonies, battles, conversations, activities",
  Time: "Dates, time periods, seasons, historical eras",
} as const;

// Prompt templates for entity extraction
export function createEntityExtractionPrompt(
  content: string,
  entityTypes: Record<string, string> = DEFAULT_ENTITY_TYPES,
  context?: {
    previousEntities?: string[];
    sourceType?: 'text' | 'message' | 'document';
  }
): string {
  const entityTypeDescriptions = Object.entries(entityTypes)
    .map(([type, description]) => `- ${type}: ${description}`)
    .join('\n');

  const sourceInstructions = getSourceInstructions(context?.sourceType || 'text');
  const contextInstructions = context?.previousEntities?.length 
    ? `\n\nPREVIOUS ENTITIES (for context):\n${context.previousEntities.join(', ')}\n`
    : '';

  return `Extract entities from this content and return them as a JSON object.

<CONTENT>
${content}
</CONTENT>

<ENTITY_TYPES>
${entityTypeDescriptions}
</ENTITY_TYPES>

${sourceInstructions}${contextInstructions}

IMPORTANT RULES:
1. Only extract entities that are explicitly mentioned in the content
2. Do NOT hallucinate or infer entities that aren't clearly present
3. Preserve original language and names exactly as written
4. For each entity, choose the most specific entity_type that applies
5. ALWAYS provide ALL fields for each entity
6. Use empty string for summary if no description is available
7. Use empty array [] for attributes if no additional data
8. Do not extract generic pronouns (he, she, it, they) without clear antecedents

Return your response as a JSON object with this exact structure (ALL fields are required):
{
  "entities": [
    {
      "name": "entity name exactly as mentioned",
      "entity_type": "most specific type from the list above",
      "summary": "brief description or empty string if none available",
      "attributes": [{"key": "attribute_name", "value": "attribute_value"}] // array of key-value pairs or empty array []
    }
  ]
}`;
}

function getSourceInstructions(sourceType: 'text' | 'message' | 'document'): string {
  switch (sourceType) {
    case 'message':
      return `
EXTRACTION FOCUS (for conversational content):
- Extract the speaker as the first entity (if identifiable)
- Focus on people, places, and objects mentioned in conversation
- Include topics and concepts discussed
- Capture any specific names, brands, or proper nouns`;

    case 'document':
      return `
EXTRACTION FOCUS (for document content):
- Extract named entities (people, places, organizations)
- Identify key concepts and topics
- Include objects and things mentioned
- Capture temporal references and events`;

    case 'text':
    default:
      return `
EXTRACTION FOCUS (for general text):
- Extract all named entities (people, places, organizations)
- Identify key concepts, topics, and themes
- Include important objects and items mentioned
- Capture events and temporal references`;
  }
}

// Reflexion prompt for improving extraction quality
export function createReflexionPrompt(
  originalContent: string,
  previousEntities: ExtractedEntity[]
): string {
  const entityList = previousEntities
    .map(e => `- ${e.name} (${e.entity_type})`)
    .join('\n');

  return `Review your previous entity extraction and identify any entities you may have missed.

<ORIGINAL_CONTENT>
${originalContent}
</ORIGINAL_CONTENT>

<PREVIOUS_EXTRACTION>
${entityList}
</PREVIOUS_EXTRACTION>

Review the original content carefully. Are there any additional entities that you missed in your previous extraction? Be conservative - only add entities that are clearly and explicitly mentioned in the content.

Return additional entities as a JSON object with this exact structure:
{
  "entities": [
    {
      "name": "entity name exactly as mentioned",
      "entity_type": "most specific type from the available types",
      "summary": "brief description if content provides details (optional)",
      "attributes": {"key": "value"} // any additional structured data (optional)
    }
    // Only include NEW entities you missed previously
  ]
}

If you didn't miss any entities, return an empty array: {"entities": []}`;
}

// Entity type validation and suggestion
export function validateEntityType(entityType: string, availableTypes: Record<string, string>): boolean {
  return entityType in availableTypes;
}

export function suggestEntityType(entityName: string, content: string): string {
  // Simple heuristics for entity type suggestion
  const name = entityName.toLowerCase();
  const context = content.toLowerCase();

  // Person indicators
  if (name.includes('mr.') || name.includes('mrs.') || name.includes('dr.') ||
      context.includes(`${name} said`) || context.includes(`${name} thinks`)) {
    return 'Person';
  }

  // Location indicators  
  if (name.includes('street') || name.includes('avenue') || name.includes('city') ||
      context.includes(`in ${name}`) || context.includes(`at ${name}`)) {
    return 'Location';
  }

  // Organization indicators
  if (name.includes('inc.') || name.includes('corp.') || name.includes('company') ||
      name.includes('university') || name.includes('school')) {
    return 'Organization';
  }

  // Default to Concept for abstract things
  return 'Concept';
}